function pick(arr) { return arr[Math.floor(Math.random() * arr.length)]; }
function rint(a, b) { return Math.floor(a + Math.random() * (b - a + 1)); }
function fmtTime(d = new Date()) {
  const h = String(d.getHours()).padStart(2, '0');
  const m = String(d.getMinutes()).padStart(2, '0');
  const s = String(d.getSeconds()).padStart(2, '0');
  return `${h}:${m}:${s}`;
}

function genLog() {
  const tpl = pick(LOG_TEMPLATES);
  const a  = pick(AGENTS);
  const a2 = pick(AGENTS.filter(x => x.id !== a.id));
  const n = rint(2, 99);
  const t = rint(20, 800);
  const text = tpl.tpl
    .replace('%a2', `<span class="agent-name">${a2.name}</span>`)
    .replace('%a',  `<span class="agent-name">${a.name}</span>`)
    .replace(/%n/g, `<span class="num">${n}</span>`)
    .replace(/%t/g, `<span class="num">${t}</span>`);
  return { lvl: tpl.lvl, text, time: fmtTime() };
}

